#include <vector>
#include <string>
using namespace std;

int main() {
    long long n;
    cin >> n;

    long long zeros = 0;
    while (n > 0) {
        n /= 5;
        zeros += n;
    }
    cout << zeros << endl;

    return 0;
}

code.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();

        long zeros = 0;
        while (n > 0) {
            n /= 5;
            zeros += n;
        }
        System.out.println(zeros);
    }
}
